    private static var cache: [String: NSImage] = [:]

    /// The mark as a vector image in one colour (macOS renders SVG natively).
    @MainActor static func image(_ id: String, white: Bool) -> NSImage? {
        let key = id + (white ? "/w" : "/k")
        if let hit = cache[key] { return hit }
        guard let m = marks[id] else { return nil }
        let fill = white ? "#FFFFFF" : "#000000"
        let svg = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path fill=\"\(fill)\" d=\"\(m.path)\"/></svg>"
        guard let img = NSImage(data: Data(svg.utf8)) else { return nil }
        cache[key] = img
        return img
    }

    /// A brand-coloured app-icon tile with the white mark (Notion: white tile, black mark); a letter badge otherwise.
    struct Tile: View {
        let id: String
        let name: String
        let fallback: UInt32
        var size: CGFloat = 26

        var body: some View {
            let mark = ConnectorLogo.marks[id]
            let rgb = mark?.hex ?? fallback
            let dark = rgb == 0x000000
            let bg = dark ? Color.white : PaletteCode.color(rgb)
            ZStack {
                RoundedRectangle(cornerRadius: size * 0.27, style: .continuous)
                    .fill(LinearGradient(colors: [bg.mix(.white, dark ? 0 : 0.12), bg], startPoint: .top, endPoint: .bottom))
                RoundedRectangle(cornerRadius: size * 0.27, style: .continuous).strokeBorder(.white.opacity(0.14), lineWidth: 0.5)
                if mark != nil, let img = ConnectorLogo.image(id, white: !dark) {
                    Image(nsImage: img).resizable().interpolation(.high).aspectRatio(contentMode: .fit)
                        .padding(size * 0.2)
                } else {
                    Text(String(name.prefix(1)).uppercased())
                        .font(.system(size: size * 0.5, weight: .bold, design: .rounded)).foregroundStyle(.white)
                }
            }
            .frame(width: size, height: size)
            .shadow(color: (dark ? Color.white : bg).opacity(0.25), radius: 3, y: 1)
            .accessibilityLabel(name)
        }
    }
